#!/usr/bin/env bash
# Documentation : l'ordre des disciplines, du menu à la galerie.
# Prérequis : apply-fix-ordre-disciplines.sh. Aucune migration.
# Usage (racine du repo) : bash apply-docs-ordre-disciplines.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/domaine/un-modele-qui-s-ouvre.mdx" 2>/dev/null | grep -qF "le lisent dans une seule fonction (`disciplineOrder.ts`)"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "export function compareDisciplines" "apps/web/src/features/app-shell/disciplineOrder.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-ordre-disciplines.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/domaine/ce-que-voit-le-visiteur.mdx" "apps/web/content/docs/dev/domaine/un-modele-qui-s-ouvre.mdx" "apps/web/content/docs/dev/qualite/tester-de-bout-en-bout.mdx")
EXPECT=("4e4630764ff2:apps/web/content/docs/dev/domaine/ce-que-voit-le-visiteur.mdx" "78017037289a:apps/web/content/docs/dev/domaine/un-modele-qui-s-ouvre.mdx" "d12d81b85cd2:apps/web/content/docs/dev/qualite/tester-de-bout-en-bout.mdx")
DIFF=0; for e in "${EXPECT[@]}"; do h=${e%%:*}; f=${e#*:}; c=$(git rev-parse "HEAD:$f" 2>/dev/null | cut -c1-12); if [ "$c" != "$h" ]; then [ $DIFF = 0 ] && echo "❌ ces fichiers ne sont pas dans l'état attendu (rien n'a été touché) :"; echo "   $f"; DIFF=1; fi; done; [ $DIFF = 0 ] || exit 1
CREATED=()
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "le lisent dans une seule fonction (`disciplineOrder.ts`)" "apps/web/content/docs/dev/domaine/un-modele-qui-s-ouvre.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR


python3 - <<'PY'
import base64
spec_skip_done = False
def sub(path, old, new):
    old, new = base64.b64decode(old).decode(), base64.b64decode(new).decode()
    s = open(path, encoding="utf-8").read()
    if s.count(old) == 0 and s.count(new) == 1 and spec_skip_done: return  # déjà fait par un script précédent
    assert s.count(old) == 1, (path, old[:80], s.count(old))
    open(path, "w", encoding="utf-8").write(s.replace(old, new))
sub('apps/web/content/docs/dev/domaine/ce-que-voit-le-visiteur.mdx', '',
    '')
sub('apps/web/content/docs/dev/domaine/un-modele-qui-s-ouvre.mdx', '',
    '')
sub('apps/web/content/docs/dev/qualite/tester-de-bout-en-bout.mdx', '',
    '')
sub('apps/web/content/docs/dev/qualite/tester-de-bout-en-bout.mdx', '',
    '')
print("  édits ok (4 substitutions, 0 fichiers créés, 0 remplacés)")
PY
trap - ERR

[ "${AKFC_APPLY_ONLY:-0}" = "1" ] && { echo "Appliqué (sans vérification ni commit)."; exit 0; }
echo "== pnpm check =="
if pgrep -f "next dev" >/dev/null 2>&1; then
  echo "  (pnpm dev tourne : vérification sans effacer .next)"
  CHECK="node scripts/check-next-conventions.mjs && node scripts/check-tour-targets.mjs && pnpm typecheck && pnpm lint"
else
  CHECK="pnpm check"
fi
if ! bash -c "$CHECK" > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"
  grep -nE "error TS|✗ tutos|ERR_|Error:|EACCES|Permission denied" /tmp/akfc_tc.log | head -12
  echo "  … fin du journal :"; grep -v '^[[:space:]]*$' /tmp/akfc_tc.log | tail -15
  restore; exit 1
fi
echo "  ✅ check OK"
git add -- "${MODIFIED[@]}" "${CREATED[@]}"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
